'use strict';
const assert=require('node:assert/strict');
const {position,matchesIntent,acknowledged,holdIncoming,sampleAge}=require('./playback-clock.js');
const s={connected:true,playing:true,position:80,positionMs:80250,duration:200};
assert.equal(position(s,1000,1000),80.25);
assert.equal(position(s,1000,2000),81.25);
assert.equal(position(s,1000,5000),84.25);
assert.equal(position({...s,playing:false},1000,5000),80.25);
assert.equal(position({...s,positionMs:199000},1000,5000),200);
assert.equal(position({...s,connected:false},1000,5000),0);
assert.equal(position({...s,error:'offline'},1000,5000),0);
assert.equal(position(s,1000,6000,2000),81.25);
assert.equal(position(s,1000,31000),95.25);
assert.equal(position({...s,position:40,positionMs:40000},5000,6000),41);
const current={...s,deviceId:'d',uri:'spotify:track:test'};
const pause={action:'toggle',value:false,device:'d'};
const ack=acknowledged(current,pause,82.5);
assert.equal(ack.playing,false);
assert.equal(position(ack,1000,5000),82.5);
assert.equal(matchesIntent(current,pause),false);
assert.equal(matchesIntent(ack,pause),true);
assert.equal(matchesIntent({...ack,inactive:true,deviceId:null},pause),true);
assert.equal(matchesIntent({...ack,deviceId:'other'},pause),false);
assert.equal(matchesIntent({...current,uri:'spotify:track:next'},{action:'next',device:'d',uri:current.uri,position:82}),true);
assert.equal(matchesIntent({...current,inactive:true},{action:'next',device:'d',uri:current.uri,position:82}),false);
assert.equal(matchesIntent({...current,positionMs:30000},{action:'seek',device:'d',value:30}),true);
const hold={...pause,expires:3500};
assert.equal(holdIncoming(current,hold,1000),true);
assert.equal(holdIncoming(ack,hold,1000),false);
assert.equal(holdIncoming(current,hold,3500),false);
assert.equal(holdIncoming({...current,inactive:true},hold,1000),false);
assert.equal(holdIncoming({...current,deviceId:'other'},hold,1000),false);
assert.equal(holdIncoming({...current,connected:false},hold,1000),false);
assert.equal(holdIncoming({...current,error:'failure'},hold,1000),false);
const skip={action:'next',device:'d',uri:current.uri,position:82,expires:7000};
assert.equal(holdIncoming(current,skip,4000),true);
assert.equal(holdIncoming({...current,uri:'new'},skip,4000),false);
assert.equal(holdIncoming(current,skip,7100),false);
assert.equal(sampleAge(undefined),0);
assert.equal(sampleAge(-20),0);
assert.equal(sampleAge(1750),1750);
assert.equal(sampleAge(20000),15000);
assert.equal(position(s,5000-sampleAge(1750),5000),82);
assert.equal(position({...s,playing:false},5000-sampleAge(1750),5000),80.25);
assert.equal(acknowledged({...current,shuffle:false},{action:'shuffle'},82.5).shuffle,true);
assert.equal(acknowledged({...current,repeat:'off'},{action:'repeat'},82.5).repeat,'context');
assert.equal(acknowledged({...current,saved:true},{action:'save'},82.5).saved,false);
assert.equal(acknowledged({...current,shuffle:false},{action:'shuffle'},82.5).positionMs,82500);
console.log('Playback clock and reconciliation assertions passed');
